"use client";

import { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";

const CHAR_SET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ@#$%&";

function EncryptChar({ char, index }: { char: string; index: number }) {
  const [displayChar, setDisplayChar] = useState(char === " " ? "\u00A0" : char);

  useEffect(() => {
    if (char === " ") {
      setDisplayChar("\u00A0");
      return;
    }

    // Set initial random character immediately upon mount
    setDisplayChar(CHAR_SET[Math.floor(Math.random() * CHAR_SET.length)]);

    const intervalId = setInterval(() => {
      setDisplayChar(CHAR_SET[Math.floor(Math.random() * CHAR_SET.length)]);
    }, 60);

    const timeoutId = setTimeout(() => {
      clearInterval(intervalId);
      setDisplayChar(char);
    }, index * 120);

    return () => {
      clearInterval(intervalId);
      clearTimeout(timeoutId);
    };
  }, [char, index]);

  return (
    <motion.span className="inline-block">
      {displayChar}
    </motion.span>
  );
}

